describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 10.5, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: 5.5 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () => new WeightBasedShippingCalculator(
          [{ upToGrams: 1000, costCents: 100 }],
          5.5,
        ),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () => new WeightBasedShippingCalculator(
          [{ upToGrams: 1000, costCents: 100 }],
          -1,
        ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 5000, costCents: 1200 },
      ],
      1500,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 when all items have no weight", () => {
      expect(calc.computeShippingCents([makeLine("a", 2)], 1000)).toBe(0);
    });

    it("selects first bracket when weight is within it", () => {
      const lines = [makeLine("a", 1, 400)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("selects bracket at exact boundary", () => {
      const lines = [makeLine("a", 1, 500)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("selects next bracket when weight exceeds boundary", () => {
      const lines = [makeLine("a", 1, 501)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(700);
    });

    it("selects last bracket at its boundary", () => {
      const lines = [makeLine("a", 1, 5000)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const lines = [makeLine("a", 1, 5001)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(1500);
    });

    it("uses last bracket cost as overflow when overflowCostCents not set", () => {
      const calcNoOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 1000, costCents: 500 },
        { upToGrams: 3000, costCents: 900 },
      ]);
      const lines = [makeLine("a", 1, 5000)];
      expect(calcNoOverflow.computeShippingCents(lines, 1000)).toBe(900);
    });

    it("considers quantity in weight calculation", () => {
      // 3 items × 700g = 2100g → second bracket (up to 2000) exceeded → third bracket
      const lines = [makeLine("a", 3, 700)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(1200);
    });

    it("sorts brackets regardless of input order", () => {
      const unsorted = new WeightBasedShippingCalculator([
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
      ]);
      const lines = [makeLine("a", 1, 400)];
      expect(unsorted.computeShippingCents(lines, 1000)).toBe(300);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2500, weightGrams: 300 };

describe("Cart — line management", () => {
  it("starts empty with 0 items", () => {
    const cart = new Cart();
    expect(cart.itemCount).toBe(0);
    expect(cart.totals().subtotalCents).toBe(0);
  });

  it("adds a product", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    expect(cart.itemCount).toBe(2);
  });

  it("merges quantity when adding same product twice", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(5);
    expect(cart.totals().subtotalCents).toBe(5000);
  });

  it("rejects non-positive quantity on add", () => {
    const cart = new Cart();
    expect(() => cart.add(productA, 0)).toThrow(RangeError);
    expect(() => cart.add(productA, -1)).toThrow(RangeError);
    expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents on add", () => {
    const cart = new Cart();
    const badProduct: Product = { id: "x", name: "Bad", unitPriceCents: -1 };
    expect(() => cart.add(badProduct, 1)).toThrow(RangeError);
  });

  it("removes a product and returns true", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("returns false when removing unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes quantity", () => {
    const cart = new Cart();
    cart.add(productA, 3);
    cart.updateQuantity("a", 1);
    expect(cart.itemCount).toBe(1);
  });

  it("updateQuantity 0 removes the line", () => {
    const cart = new Cart();
    cart.add(productA, 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("x", 1)).toThrow("Product x is not in the cart");
  });

  it("updateQuantity rejects negative quantity", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer quantity", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
  });

  it("clear removes all lines", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.add(productB, 1);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns a deep copy", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const snap = cart.snapshot();
    snap[0]!.quantity = 999;
    expect(cart.itemCount).toBe(2);
  });
});

describe("Cart — pricing pipeline", () => {
  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(productA, 2); // 2000
    cart.add(productB, 1); // 2500
    expect(cart.totals().subtotalCents).toBe(4500);
  });

  it("applies discount, then tax on discounted subtotal, then shipping", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(100),
    };
    const mockShipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(300),
    };

    const cart = new Cart({
      discountPolicy: mockDiscount,
      taxCalculator: mockTax,
      shippingCalculator: mockShipping,
      region: "US-CA",
    });
    cart.add(productA, 2); // subtotal = 2000

    const totals = cart.totals();

    expect(totals.subtotalCents).toBe(2000);
    expect(totals.discountCents).toBe(500);
    // Tax computed on discounted subtotal (2000 - 500 = 1500)
    expect(mockTax.computeTaxCents).toHaveBeenCalledWith(1500, "US-CA");
    expect(totals.taxCents).toBe(100);
    // Shipping receives lines and discounted subtotal
    expect(mockShipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      1500,
    );
    expect(totals.shippingCents).toBe(300);
    // total = discountedSubtotal + tax + shipping = 1500 + 100 + 300
    expect(totals.totalCents).toBe(1900);
  });

  it("clamps discount to [0, subtotal]", () => {
    const overDiscount: DiscountPolicy = {
      computeDiscountCents: () => 99999,
    };
    const cart = new Cart({ discountPolicy: overDiscount });
    cart.add(productA, 1); // subtotal = 1000

    const totals = cart.totals();
    expect(totals.discountCents).toBe(1000);
    expect(totals.totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const negDiscount: DiscountPolicy = {
      computeDiscountCents: () => -100,
    };
    const cart = new Cart({ discountPolicy: negDiscount });
    cart.add(productA, 1);

    expect(cart.totals().discountCents).toBe(0);
  });

  it("clamps negative tax to 0", () => {
    const negTax: TaxCalculator = {
      computeTaxCents: () => -50,
    };
    const cart = new Cart({ taxCalculator: negTax });
    cart.add(productA, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const negShipping: ShippingCalculator = {
      computeShippingCents: () => -50,
    };
    const cart = new Cart({ shippingCalculator: negShipping });
    cart.add(productA, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("defaults to NoDiscount, NoTax, FreeShipping, region US", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
    expect(totals.taxCents).toBe(0);
    expect(totals.shippingCents).toBe(0);
    expect(totals.totalCents).toBe(1000);
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { Product } from "../src/product.ts";
import { PercentageDiscountPolicy } from "../src/pricing.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000 };

describe("Cart.checkout()", () => {
  describe("price refresh", () => {
    it("refreshes prices via priceFetcher before computing totals", async () => {
      const cart = new Cart();
      cart.add(productA, 2);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };

      const result = await cart.checkout({ priceFetcher });
      // Prices updated: 1500 * 2 = 3000
      expect(result.totals.subtotalCents).toBe(3000);
      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    });

    it("throws RangeError when fetcher returns invalid price", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(-5),
      };

      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(RangeError);
    });

    it("throws RangeError when fetcher returns non-integer price", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(10.5),
      };

      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(RangeError);
    });

    it("propagates fetcher rejection", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("service down")),
      };

      await expect(cart.checkout({ priceFetcher })).rejects.toThrow("service down");
    });
  });

  describe("inventory check", () => {
    it("succeeds when inventory is available", async () => {
      const cart = new Cart();
      cart.add(productA, 2);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };

      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(2000);
      expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const cart = new Cart();
      cart.add(productA, 5);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 2,
          reason: "low stock",
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("a");
        expect(invErr.requested).toBe(5);
        expect(invErr.available).toBe(2);
        expect(invErr.message).toBe("low stock");
      }
    });

    it("throws InventoryError on partial-stock denial (available=true but qty insufficient)", async () => {
      const cart = new Cart();
      cart.add(productA, 10);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("a");
        expect(invErr.requested).toBe(10);
        expect(invErr.available).toBe(3);
      }
    });

    it("checks each line and fails on first denial", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      cart.add(productB, 1);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn()
          .mockResolvedValueOnce({ available: true })
          .mockResolvedValueOnce({ available: false, reason: "out of stock" }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("b");
      }
    });
  });

  describe("async tax provider", () => {
    it("uses async tax provider for tax calculation", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(10),
        shippingCalculator: new FlatShippingCalculator(500),
      });
      cart.add(productA, 2); // subtotal 2000, discount 200 → taxable 1800

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };

      const result = await cart.checkout({ asyncTaxProvider });
      expect(result.totals.subtotalCents).toBe(2000);
      expect(result.totals.discountCents).toBe(200);
      // tax = floor(1800 * 0.1) = 180
      expect(result.totals.taxCents).toBe(180);
      expect(result.totals.shippingCents).toBe(500);
      // total = 1800 + 180 + 500 = 2480
      expect(result.totals.totalCents).toBe(2480);
    });

    it("propagates async tax provider rejection", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };

      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow("tax service down");
    });

    it("throws RangeError for invalid async rate", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(2.0),
      };

      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(RangeError);
    });
  });

  describe("full pipeline composition", () => {
    it("combines price refresh, inventory check, and async tax", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(20),
        shippingCalculator: new FlatShippingCalculator(400),
      });
      cart.add(productA, 2);
      cart.add(productB, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn()
          .mockResolvedValueOnce(1200) // product a
          .mockResolvedValueOnce(2500), // product b
      };

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.08),
      };

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // refreshed subtotal: 1200*2 + 2500*1 = 4900
      expect(result.totals.subtotalCents).toBe(4900);
      // discount: 20% of 4900 = 980
      expect(result.totals.discountCents).toBe(980);
      // taxable: 4900 - 980 = 3920, tax = floor(3920 * 0.08) = 313
      expect(result.totals.taxCents).toBe(313);
      expect(result.totals.shippingCents).toBe(400);
      // total = 3920 + 313 + 400 = 4633
      expect(result.totals.totalCents).toBe(4633);

      expect(result.lines).toHaveLength(2);
    });

    it("works with no collaborators (uses defaults)", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const result = await cart.checkout();
      expect(result.totals.totalCents).toBe(1000);
    });
  });
});

